'use strict';
const E=CFEngine,T=CFTiled,$=id=>document.getElementById(id),range=E.range;
const fields=[['a','Array size A'],['n','Images N'],['c','Input channels C'],['k','Output channels K'],['h','Input height H'],['w','Input width W'],['r','Kernel height R'],['s','Kernel width S'],['pad_i','Padding i'],['pad_j','Padding j'],['stride_i','Stride i'],['stride_j','Stride j'],['dilation_i','Dilation i'],['dilation_j','Dilation j'],['ia','Input addr bits'],['oa','Output addr bits'],['ka','Kernel addr bits']];
let sim,raw,x,w,timer=null,selected=[0,0],tab='input',valid=true,matrixRow=0,matrixCol=0,kernelPage=0;
const fmt=v=>v===null?'—':String(v),small=v=>v===null?'—':String(v),rows=(head,data)=>`<div class="scroll"><table><thead><tr>${head.map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${data.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function pause(){if(timer)clearInterval(timer);timer=null;$('play').textContent='▶ Play';}
function error(e){pause();valid=false;$('error').textContent=e.message;for(const id of ['play','step','back','nextState','nextTap','finish','seek'])$(id).disabled=true;}
function init(d,xx,ww){const next=T.create(d,xx,ww);pause();sim=next;raw={...d};x=next.x;w=next.w;valid=true;matrixRow=matrixCol=kernelPage=0;selected=[Math.min(selected[0],d.a-1),Math.min(selected[1],d.a-1)];$('error').textContent='';$('batch').innerHTML=range(d.n).map(n=>`<option>${n}</option>`).join('');render();}
function editors(d,xx,ww){const grid=(side,h,v,fn)=>`<div class="tensor-grid" style="grid-template-columns:repeat(${v},51px)">${range(h).flatMap(i=>range(v).map(j=>{const [idx,value,label]=fn(i,j);return `<input type="number" min="-128" max="127" step="1" data-side="${side}" data-index="${idx}" value="${value}" aria-label="${label}">`;})).join('')}</div>`;let a='',b='';for(let n=0;n<d.n;n++)for(let c=0;c<d.c;c++)a+=`<div class="tensor-card"><h4>Image ${n} · channel ${c}</h4>${grid('x',d.h,d.w,(h,v)=>{const i=E.xindex(d,n,c,h,v);return [i,xx[i],`X[${n},${c},${h},${v}]`];})}</div>`;for(let k=0;k<d.k;k++)for(let c=0;c<d.c;c++)b+=`<div class="tensor-card"><h4>Filter ${k} · channel ${c}</h4>${grid('w',d.r,d.s,(r,s)=>{const i=E.windex(d,k,c,r,s);return [i,ww[i],`W[${k},${c},${r},${s}]`];})}</div>`;$('inputEditors').innerHTML=a;$('weightEditors').innerHTML=b;}
function readCells(side){return [...document.querySelectorAll(`[data-side=${side}]`)].map(el=>{const v=Number(el.value);if(el.value.trim()===''||!Number.isInteger(v)||v< -128||v>127)throw Error('Every tensor cell needs a signed 8-bit integer (−128…127).');return v;});}
function edit(){try{const d=T.config(Object.fromEntries(fields.map(([key])=>[key,$('cfg-'+key).value.trim()===''?NaN:Number($('cfg-'+key).value)]))),old=sim.layer.d,xx=readCells('x'),ww=readCells('w'),nx=range(d.n*d.c*d.h*d.w).map(i=>{const v=i%d.w,h=Math.floor(i/d.w)%d.h,c=Math.floor(i/(d.w*d.h))%d.c,n=Math.floor(i/(d.w*d.h*d.c));return n<old.n&&c<old.c&&h<old.h&&v<old.w?xx[E.xindex(old,n,c,h,v)]:1;}),nw=range(d.k*d.c*d.r*d.s).map(i=>{const s=i%d.s,r=Math.floor(i/d.s)%d.r,c=Math.floor(i/(d.s*d.r))%d.c,k=Math.floor(i/(d.s*d.r*d.c));return k<old.k&&c<old.c&&r<old.r&&s<old.s?ww[E.windex(old,k,c,r,s)]:0;});if(['n','c','h','w','k','r','s'].some(key=>d[key]!==old[key]))editors(d,nx,nw);init(d,nx,nw);}catch(e){error(e);}}
function preset(kind){let cfg={...E.defaults};if(kind==='tiled')Object.assign(cfg,{a:3,n:2,c:5,k:4,h:3,w:5,r:2,s:2,ia:3,oa:1,ka:3});if(kind==='fallback')Object.assign(cfg,{a:2,c:3,k:3,h:3,w:4,r:2,s:2,ia:2,oa:1,ka:1,pad_i:1,pad_j:1,dilation_i:2});if(kind==='empty')Object.assign(cfg,{a:2,c:1,k:1,h:1,w:1,r:1,s:1,pad_i:2,pad_j:2,ia:1,oa:1,ka:1});if(kind==='slides')Object.assign(cfg,{c:2,k:2,h:4,w:4,r:2,s:2,stride_i:2,stride_j:2});if(kind==='batch')Object.assign(cfg,{n:2,c:2,k:3,h:3,w:3,r:1,s:2});if(kind==='padding')Object.assign(cfg,{c:2,k:2,h:4,w:5,r:2,s:2,pad_i:1,pad_j:1,stride_i:2,stride_j:1,dilation_i:2,dilation_j:2});if(kind==='signed')Object.assign(cfg,{a:3,c:3,k:2,h:2,w:3,r:1,s:2});if(kind==='default')Object.assign(cfg,{a:10,c:4,k:2,h:6,w:6,r:3,s:3});const d=T.config(cfg),xx=range(d.n*d.c*d.h*d.w).map(i=>kind==='signed'?(i*37%256)-128:(i%9)+1),ww=range(d.k*d.c*d.r*d.s).map(i=>kind==='signed'?(i*53%256)-128:[1,0,-1,1,2,-1][i%6]);fields.forEach(([key])=>$('cfg-'+key).value=d[key]);editors(d,xx,ww);init(d,xx,ww);}
function step(){if(valid&&!sim.finished){clockEdge(sim);render(true);if(sim.finished)pause();}}
function seek(edge){if(!valid)return;pause();const next=T.create(raw,sim.layer.X,sim.layer.W);while(next.edge<edge&&!next.finished)clockEdge(next);sim=next;x=next.x;w=next.w;render();}
function advance(kind){if(!valid||sim.finished)return;pause();const state=sim.layer.state+sim.state,tap=sim.layer.job+':'+sim.r*sim.d.s+':'+sim.s;do{clockEdge(sim);}while(!sim.finished&&(kind==='finish'||kind==='state'&&sim.layer.state+sim.state===state||kind==='tap'&&sim.layer.job+':'+sim.r*sim.d.s+':'+sim.s===tap));render();}
function play(){if(timer){pause();return;}if(!valid||sim.finished)return;$('play').textContent='Ⅱ Pause';step();if(!sim.finished)timer=setInterval(step,Number($('speed').value));}
function renderLocal(animate=false){const s=sim,d=s.d,e=s.event,ctl=E.controls(s);displayedQueueLimit=queuePreviewLimit();const forecast=operandQueues(s,displayedQueueLimit);$('shapeSummary').textContent=`${d.n}×${d.c}×${d.h}×${d.w} → ${d.n}×${d.k}×${d.p}×${d.q} · ${d.a}×${d.a} array`;$('capacity').innerHTML=[`Input ${d.n*d.h*d.w} / ${2**d.ia}`,`Output ${d.m} / ${2**d.oa}`,`Kernel ${d.c*d.r*d.s} / ${2**d.ka}`].map(v=>`<span>${v} words / bank</span>`).join('');$('clock').textContent=s.cycles;$('clockTotal').textContent=`/ ${d.total}`;$('edge').textContent=s.edge;$('seek').max=d.total+1;$('seek').value=s.edge;$('runLabel').textContent=`RUN ${s.runCount} / ${d.run} · active buffer ${s.active}`;$('phasebar').innerHTML=['IDLE','PRIME','LOAD_WEIGHTS','RUN','SWITCH_TAP'].map(v=>`<span class="${s.state===v?'active':''}">${v}${v==='IDLE'&&s.finished?' · done':''}</span>`).join('');$('arraySubtitle').textContent=`${d.a} × ${d.a} physical PEs · row c = input channel · column k = filter`;$('tapBadge').textContent=`Tap ${s.r*d.s+s.s+1} / ${d.taps}`;
 const stories={IDLE:s.finished?['Layer complete · done = 1','All active output SRAM words are committed. The controller is idle; the done pulse follows the final RUN edge.']:['Ready to accept start','Input and kernel SRAM are already preloaded for this teaching run. Step once to capture configuration and accept start.'],PRIME:['Prime the kernel SRAM','One synchronous read fetches the first physical load row. The sum pipeline is held clear.'],LOAD_WEIGHTS:['Load stationary weights','Weights shift downward into buffer 0, from physical row A−1 toward row 0. All physical rows take part, including inactive rows.'],RUN:[`Compute tap (r=${s.r}, s=${s.s}) · buffer ${s.active}`,`${s.r||s.s?'Output SRAM adds this tap to the saved partial sum.':d.continue?'The first tap continues resident output sums.':'The first contribution initializes output SRAM.'} ${ctl.hasNext?'The inactive PE weight buffer receives the next tap while computation continues.':'This is the final tap; background loading is disabled.'}`],SWITCH_TAP:['Switch tap after all writes commit','The active weight buffer has toggled. This cleared cycle resets stream/writeback counters and prefetches position zero; SRAM contents remain.']};$('storyTitle').textContent=stories[s.state][0];$('storyText').textContent=stories[s.state][1];
 let html='<div class="queue-key"><b>Stream preview</b><b class="quiet-symbol" aria-hidden="true">→ ↓</b><span>Next value is closest to the array.</span><small>Inputs → · weights ↓<br>Visual preview only</small></div>'+range(d.a).map(k=>`<div class="axis weight-source" data-weight-source="${k}">${weightQueueHTML(k,forecast)}</div>`).join('');for(let c=0;c<d.a;c++){html+=`<div class="feeder" data-feeder="${c}">${inputQueueHTML(c,forecast)}</div>`;for(let k=0;k<d.a;k++){const p=s.pe[c][k],active=c<d.c&&k<d.k;html+=`<button class="pe ${selected[0]===c&&selected[1]===k?'selected':''} ${active?'':'masked'} ${p.token?'lit':''}" data-pe="${c},${k}" aria-label="Inspect PE row ${c}, column ${k}" aria-pressed="${selected[0]===c&&selected[1]===k}"><span class="pe-id">PE [${c}, ${k}] · ${active?'active':'masked'}</span><span class="equation"><span class="teal">${p.a}</span> × <span class="amber">${p.weightUsed}</span></span><span class="sum">${p.sum}</span><span class="operand-tag ${p.token?'present':''}">${p.token?`X ${p.a} · pos ${p.token.pos}`:'no activation'}</span><span class="regs">${p.weights.map((v,b)=>`<span class="reg ${b===s.active?'active':''} ${e?.ctl.load&&b===e.ctl.writeBuffer?'loading':''}" data-buffer="${b}" title="Weight buffer ${b}${b===s.active?' · compute':' · standby'}${e?.ctl.load&&b===e.ctl.writeBuffer?' · shifted on this edge':''}">B${b} ${v}</span>`).join('')}</span></button>`;}}html+='<div class="axis">Registered column<br>output → SRAM</div>'+range(d.a).map(k=>{const wr=e?.writes.find(v=>v.k===k);return `<div class="array-out">col = ${s.col[k]}<br>${k>=d.k?'write disabled':wr?`@${wr.addr} ← ${wr.value}`:'no write this edge'}</div>`;}).join('');$('array').style.gridTemplateColumns=`128px repeat(${d.a},minmax(0,1fr))`;$('array').style.maxWidth=(128+d.a*96)+'px';$('array').innerHTML=html;$('array').classList.toggle('hidden-regs',!$('peDetails').checked);
 const [c,k]=selected,p=s.pe[c][k];$('peInspect').innerHTML=`<div class="eyebrow">SELECTED PE [${c}, ${k}] · LAST EDGE</div><p><strong><span class="purple">${p.sum}</span> = ${p.above} + <span class="teal">${p.a}</span> × <span class="amber">${p.weightUsed}</span></strong><span class="annotation">${e?.ctl.clear?' · clear_pass asserted': ' · signed 32-bit wraparound'}</span></p><span class="muted">Activation moves right; the incoming sum comes from the row above. Two stationary weight registers: B0=${p.weights[0]}, B1=${p.weights[1]}. ${p.token?`Activation belongs to stream position ${p.token.pos}.`:''}</span>`;
 const n=0;$('outputs').innerHTML=range(d.k).map(k=>`<div class="map sram-output-bank" data-output-bank="${k}" style="--bank-color:${tensorColor('w',k,0)}"><h3>k=${k}</h3><div class="map-grid" style="--map-cols:${d.q};grid-template-columns:repeat(${d.q},minmax(0,1fr))">${range(d.p*d.q).map(i=>{const addr=i*d.n+n,v=s.mem[k][addr],cnt=s.writes[k][addr],fresh=e?.writes.some(z=>z.k===k&&z.addr===addr),ref=T.partialReference(s,k,i);return `<div class="cell ${v===null?'':'written'} ${fresh?'fresh':''}" title="Bank ${k} · image ${n} · @${addr} · ${cnt}/${d.taps} taps">${fmt(v)}<small>@${addr} · ${cnt}/${d.taps} taps</small>${$('reference').checked?`<span class="expected">ref ${ref}</span>`:''}</div>`;}).join('')}</div></div>`).join('');const count=s.writes.flat().reduce((a,b)=>a+b,0),total=d.k*d.m*d.taps;$('progress').style.width=`${100*count/total}%`;$('result').textContent=s.finished?(T.check(s).ok?`✓ All ${d.k*d.m} outputs match the reference.`:'Mismatch: inspect the exported run.'):`${count} / ${total} output SRAM writes committed`;
 for(const id of ['play','step','nextState','nextTap','finish'])$(id).disabled=!valid||s.finished;$('back').disabled=!valid||s.edge===0;$('seek').disabled=!valid;renderModule();renderTensors();renderInputMatrix(forecast);fitWindows();renderFlows(animate);}
function renderModuleLocal(){const s=sim,d=s.d,e=s.event,ctl=E.controls(s),body=$('moduleBody');if(tab==='input'){const pos=Math.min(d.m-1,Math.max(0,e?.activations[selected[0]]?.token?.pos??0)),z=E.address(d,pos,s.r,s.s),c=Math.min(selected[0],d.c-1);body.innerHTML=`<div class="module-grid"><div><h3>One shared address, independent channel SRAMs</h3><p class="muted small">For each output coordinate, n varies fastest. The address generator looks one position ahead to hide the synchronous read latency. Feeder row c delays the feed bundle by c cycles.</p><div class="formula">n = position % N<br>p = floor(position / N / Q)<br>q = floor(position / N) % Q<br>h = p·stride_i + r·dilation_i − pad_i<br>w = q·stride_j + s·dilation_j − pad_j<br>input bank = c · address = (h·W + w)·N + n</div><p class="small">Inspected position ${pos} → n=${z.n}, p=${z.p}, q=${z.q} → h=${z.h}, w=${z.w}. ${z.valid?`SRAM address ${z.addr}.`:'Padding: address 0 is presented and activation is masked to zero.'}</p><div class="patch" style="grid-template-columns:repeat(${d.w},37px)">${range(d.h*d.w).map(i=>`<span class="${Math.floor(i/d.w)===z.h&&i%d.w===z.w?'active':''}">${x[E.xindex(d,z.n,c,Math.floor(i/d.w),i%d.w)]}</span>`).join('')}</div><span class="small muted">Input image ${z.n}, channel ${c}. Select a PE row to inspect another input channel.</span></div><div><h3>Feeder inputs sampled on the last edge</h3>${rows(['Row c','Stream pos','SRAM addr','Read valid','Activation'],range(d.a).map(c=>{const f=e?.activations[c],t=f?.token;return [c,t?.pos??'—',t?.addr??'—',c>=d.c?'inactive':t?t.valid?'image':'padding':'idle',f?.value??0];}))}<h3>Virtual im2col column · current tap</h3><p class="muted small">Computed on demand; this expanded matrix is never stored by the RTL.</p>${rows(['c / position',...range(Math.min(d.m,8))],range(d.c).map(c=>[c,...range(Math.min(d.m,8)).map(pos=>{const z=E.address(d,pos,s.r,s.s);return z.valid?x[E.xindex(d,z.n,c,z.h,z.w)]:0;})]))}</div></div>`;}
 else if(tab==='weights'){body.innerHTML=`<div class="module-grid"><div><h3>Compute from B${s.active}; prepare B${1-s.active}</h3><p class="muted small">Each PE owns two 8-bit stationary weight registers. Initial loading takes one PRIME read plus A descending shifts. During RUN, a prefetch and A shifts prepare the next tap independently of arithmetic.</p><div class="formula">kernel bank = k<br>kernel address = (c_read·R + r)·S + s<br>load order: ${range(d.a).reverse().join(' → ')}<br>active buffer = ${s.active}<br>loader phase = ${s.loadPhase}<br>next c_load = ${s.loadRow}</div><p class="small">${e?.ctl.kernelRead?`Last edge read kernel address ${e.kernelAddr}, c_read=${e.ctl.readRow}, tap (${e.ctl.kr},${e.ctl.ks}).`:'No kernel read on the last edge.'} ${e?.ctl.load?`Weights shifted into B${e.ctl.writeBuffer}.`:'No weight shift on the last edge.'}</p><p class="muted small">The active buffer toggles only after all output words for the current tap have committed. There is no whole-kernel SRAM ping-pong buffer.</p></div><div><h3>PE stationary weight registers</h3>${rows(['PE [c,k]','B0','B1','Active'],range(d.a).flatMap(c=>range(d.a).map(k=>[`[${c},${k}]`,s.pe[c][k].weights[0],s.pe[c][k].weights[1],`B${s.active}`])))}</div></div>`;}
 else if(tab==='output'){body.innerHTML=`<div class="module-grid"><div><h3>One accumulator SRAM per output column</h3><div class="formula">output bank = k<br>address = (p·Q + q)·N + n<br>WB_START_CYCLE = k + A + 1<br>first contribution: memory[address] ← column result<br>later taps / continuation: memory[address] ← old + result</div><p class="muted small">The SRAM read address anticipates the next write pointer. Its synchronous read returns the old partial sum for read-modify-write. Each logical address is written once per tap.</p><p class="small">Writeback count now ${s.wbCount}. Registered column outputs shown in the array are live pipeline results; the green output maps show stored SRAM words.</p></div><div><h3>Writes committed on the last edge</h3>${rows(['Bank k','Addr','(n,p,q)','Old','Tap result','Stored'],e?.writes.length?e.writes.map(v=>[v.k,v.addr,`(${v.n},${v.p},${v.q})`,e.r||e.s||d.continue?fmt(v.before):'overwrite',v.result,v.value]):[['—','—','—','—','—','—']])}<h3>Per-column timing</h3>${rows(['Column k','First write count','Next pointer','Live result'],range(d.a).map(k=>[k,k+d.a+1,k<d.k?s.ptr[k]:'disabled',s.col[k]]))}</div></div>`;}
 else {body.innerHTML=`<div class="module-grid"><div><h3>A pass per kernel tap</h3><div class="formula">M = N·P·Q = ${d.m}<br>T = R·S = ${d.taps}<br>RUN per tap = M + 2A = ${d.run}<br>cycles after start = 1 + A + T·(M + 2A) + (T−1)<br>= ${d.total} clocks</div><p class="muted small">The accepted start edge is rising edge 1 and elapsed clock 0. PRIME, initial weight shifts, all RUN cycles and inter-tap clears count toward start-to-done latency. Preloading SRAM is outside this interval.</p><p class="small">Channel occupancy: ${d.c*d.k} / ${d.a*d.a} PEs (${(100*d.c*d.k/d.a**2).toFixed(1)}%). This describes occupied channels, not switching activity or throughput.</p></div><div><h3>Select a tap to seek to its RUN entry</h3><div class="taps">${range(d.taps).map(t=>`<button data-tap="${t}" class="${t===s.r*d.s+s.s?'current':''}">(${Math.floor(t/d.s)}, ${t%d.s}) · B${t%2}</button>`).join('')}</div><p class="muted small">The complete local tensors must fit their banks and C,K must fit the physical array. The accelerator schedules these local jobs and DMA transfers. Browser simulation does not establish physical timing closure.</p></div></div>`;}}
// Track weight identities alongside the unchanged arithmetic model. Forwarding
// registers retain their old contents between shifts, including across taps.
const weightOrigins=new WeakMap();
function clockEdge(state){
 const d=state.d,previous=weightOrigins.get(state)??range(d.a).map(()=>range(d.a).map(()=>null));
 T.step(state);x=state.x;w=state.w;const e=state.event;
 if(e?.ctl.load)weightOrigins.set(state,range(d.a).map(c=>range(d.a).map(k=>{
  if(k>=d.k||c>=d.c)return null;
  return c?previous[c-1][k]:e.loadRow<d.c?{c:e.loadRow,k,r:e.ctl.kr,s:e.ctl.ks}:null;
 })));
}

// A bounded look-ahead on a cloned model provides the exact future lane inputs.
// These are stream previews; they do not introduce hardware FIFOs.
function operandQueues(state,limit=4){const d=state.d,result={limit,inputs:range(d.a).map(()=>[]),weights:range(d.a).map(()=>[]),inputRemaining:Array(d.a).fill(0),weightRemaining:0};if(state.finished||state.layer.state!=='WAIT_CORE'||state.layer.coreDone)return result;let weightTap=null;const future=E.clone({...state,layer:undefined}),tap=state.r*d.s+state.s,ctl=E.controls(state),pending=state.state==='IDLE'||state.state==='PRIME'||state.state==='LOAD_WEIGHTS'||state.state==='SWITCH_TAP'&&ctl.hasNext||ctl.preload&&state.loadPhase!=='WEIGHTS_READY';
 for(let after=1;after<=3*d.a+limit+4;after++){E.step(future);const e=future.event;if(e.r*d.s+e.s!==tap)break;for(let c=0;c<d.c;c++){const f=e.activations[c],t=f.token;if(!t||t.pos>=d.m||result.inputs[c].length>=limit)continue;const z=E.address(d,t.pos,e.r,e.s);result.inputs[c].push({...z,value:f.value,after,c});}if(e.ctl.load){const loadKey=`${e.ctl.kr},${e.ctl.ks},${e.ctl.writeBuffer}`;if(weightTap===null)weightTap=loadKey;for(let k=0;k<d.k;k++){if(loadKey!==weightTap||result.weights[k].length>=limit)continue;result.weights[k].push({value:future.pe[0][k].wo,c:e.loadRow,k,r:e.ctl.kr,s:e.ctl.ks,buffer:e.ctl.writeBuffer,masked:e.loadRow>=d.c,after});}}if(future.finished)break;if(result.inputs.slice(0,d.c).every(v=>v.length>=Math.min(limit,d.m))&&(!pending||result.weights[0].length>=Math.min(limit,state.state==='LOAD_WEIGHTS'||ctl.preload?state.loadRow+1:d.a)))break;}
 for(let c=0;c<d.c;c++)result.inputRemaining[c]=result.inputs[c].length?d.m-result.inputs[c][0].pos:0;result.weightRemaining=result.weights[0]?.length?result.weights[0][0].c+1:0;return result;}
function queueChip(item,index,type){const weight=type==='weight',description=weight?`W[${item.k},${item.c},${item.r},${item.s}]${item.masked?' · inactive physical row: masked zero':''}`:`X[${item.n},${item.c},${item.h},${item.w}]${item.valid?'':' · padding zero'}`;return `<span class="queue-chip ${index===0?'queue-head':''} ${weight?'weight-chip':'input-chip'} ${weight?item.masked?'queue-zero':'':!item.valid?'queue-zero':''}" data-order="${index}" data-after="${item.after}" data-value="${item.value}" ${weight?(item.masked?'':originAttrs('w',item.k,item.c,item.r,item.s)):(item.valid?originAttrs('x',item.n,item.c,item.h,item.w):'')} ${weight?`data-source-c="${item.c}" data-r="${item.r}" data-s="${item.s}" data-buffer="${item.buffer}"`:`data-pos="${item.pos}" data-n="${item.n}" data-h="${item.h}" data-w="${item.w}"`} title="${description} = ${item.value}; enters after ${item.after} clock edge${item.after===1?'':'s'}"><b>${item.value}</b><small>${weight?`c${item.c}${item.masked?' · mask':''}`:item.valid?`n${item.n} · ${item.h},${item.w}`:'pad 0'}</small>${index===0?'<em>next</em>':''}</span>`;}
function inputQueueHTML(c,forecast){const d=sim.d,list=forecast.inputs[c],remaining=forecast.inputRemaining[c],last=sim.event?.activations[c];return `<div class="queue-label"><span class="annotation">${c<d.c?'Input preview':'Inactive input row'}</span> <span>c = ${c}</span></div><div class="input-queue" data-input-queue="${c}">${remaining>list.length?`<span class="queue-more" title="${remaining-list.length} more input values after this preview">+${remaining-list.length}</span>`:''}${list.map((v,i)=>queueChip(v,i,'input')).reverse().join('')}${!list.length?`<span class="queue-empty">${c>=d.c?'masked':sim.finished?'done':'pass complete'}</span>`:''}<span class="queue-port">→</span></div><div class="queue-caption">${list.length?`${remaining} left · next in ${list[0].after} clk`:'No upcoming input for this pass'}<span>${last?.token?`last edge: ${last.value}`:'last edge: —'}</span></div>`;}
