$('matrixPager').addEventListener('click',ev=>{const button=ev.target.closest('[data-matrix-page]');if(!button)return;const [axis,delta]=button.dataset.matrixPage.split(':');if(axis==='row')matrixRow+=Number(delta);else matrixCol+=Number(delta);showSource(null);renderInputMatrix();});
document.addEventListener('pointerover',ev=>{const el=sourceElement(ev.target),previous=ev.relatedTarget instanceof Element?sourceElement(ev.relatedTarget):null;if(el!==previous)showSource(el??sourceElement(document.activeElement));});
