function stackSVG(kind,id,front,spread){const d=sim.d,{r,s}=displayedTap(),h=kind==='x'?d.h:d.r,wid=kind==='x'?d.w:d.s,cell=Math.max(22,Math.min(34,240/Math.max(h,wid))),dx=spread?wid*cell+30:28,dy=spread?0:24,sw=wid*cell+(d.c-1)*dx+12,sh=h*cell+(spread?0:(d.c-1)*dy)+36,pass=new Set();if(kind==='x')for(let pos=0;pos<d.m;pos++){const z=E.address(d,pos,r,s);if(z.valid)pass.add(`${z.h},${z.w}`);}
 const order=range(d.c).reverse().filter(c=>c!==front);order.push(front);let html=`<svg class="tensor-stack" width="${sw}" height="${sh}" viewBox="0 0 ${sw} ${sh}" role="img" aria-label="${kind==='x'?'Input image':'Kernel filter'} ${id}, ${d.c} stacked channel planes"><title>${kind==='x'?'Image':'Filter'} ${id}: one 2D plane per input channel</title>`;
 for(const c of order){const ox=6+c*dx,oy=28+(spread?0:(d.c-1-c)*dy),fed=kind==='x'?fedInput(c):null,e=sim.event,loading=kind==='w'&&e?.ctl.load,lr=e?.ctl.kr,ls=e?.ctl.ks;html+=`<g class="channel-plane" data-channel="${c}" data-stack="${kind}" data-stack-id="${id}"><rect x="${ox-2}" y="${oy-23}" width="74" height="20" rx="4" fill="${tensorColor(kind,id,c)}" stroke="${c===front?'#173c46':'#829291'}"/><text x="${ox+5}" y="${oy-9}" font-size="11" font-weight="700" fill="#173c46">c = ${c}${c===front?' · front':''}</text>`;
 for(let i=0;i<h;i++)for(let j=0;j<wid;j++){const used=kind==='x'?pass.has(`${i},${j}`):i===r&&j===s,now=kind==='x'&&fed?.valid&&fed.n===id&&fed.h===i&&fed.w===j,pre=loading&&i===lr&&j===ls,value=kind==='x'?x[E.xindex(d,id,c,i,j)]:w[E.windex(d,id,c,i,j)],cx=ox+j*cell,cy=oy+i*cell;html+=`<g><title>${kind==='x'?`X[${id},${c},${i},${j}]`:`W[${id},${c},${i},${j}]`} = ${value}${used?' · current tap pass':''}${now?' · fed on last edge':''}${pre?' · tap being loaded':''}</title><rect class="tensor-cell ${used?'tap-used':''} ${now?'input-fed':''} ${pre?'tap-loading':''}" data-kind="${kind}" data-id="${id}" data-c="${c}" data-i="${i}" data-j="${j}" x="${cx}" y="${cy}" width="${cell}" height="${cell}" fill="${now?'#087e8b':tensorColor(kind,id,c)}" stroke="${now?'#023e49':pre?'#b77711':used?'#677a83':'#556b6a'}" stroke-width="${now||pre?3:1}" ${pre?'stroke-dasharray="5 2"':''}/><text x="${cx+cell/2}" y="${cy+cell/2+4}" text-anchor="middle" font-family="ui-monospace,Consolas,monospace" font-size="${value<-99?10:12}" font-weight="${used?700:500}" fill="${now?'white':'#203d45'}">${fmt(value)}</text>${now?`<circle cx="${cx+cell-5}" cy="${cy+5}" r="3" fill="#fff"/>`:''}</g>`;}
 html+=`<rect x="${ox}" y="${oy}" width="${wid*cell}" height="${h*cell}" fill="none" stroke="${c===front?'#173c46':'#607873'}" stroke-width="${c===front?2:1}"/></g>`;}
 return html+'</svg>';}
function renderTensors(){const d=sim.d,e=sim.event,{r,s}=displayedTap(),front=Math.min(selected[0],d.c-1),spread=$('spreadChannels').checked;$('tensorPass').textContent=`Tap (r=${r}, s=${s}) · pass ${r*d.s+s+1} / ${d.taps} · ${!e?'ready to start':e.r!==r||e.s!==s?'next pass · pipeline clearing':'highlights show inputs fed on the last edge'}`;$('channelSelect').innerHTML=range(d.c).map(c=>`<button data-front="${c}" aria-pressed="${front===c}" style="--channel:${channelColors[c]}">c = ${c}</button>`).join('');$('inputStacks').innerHTML=range(d.n).map(n=>`<div class="stack-card"><h4>Image n = ${n} <small>${d.c} channel${d.c===1?'':'s'} · ${d.h} × ${d.w}</small></h4><div class="stack-scroll">${stackSVG('x',n,front,spread)}</div></div>`).join('');$('kernelStacks').innerHTML=range(d.k).map(k=>`<div class="stack-card"><h4>Filter k = ${k} <small>${d.c} channel${d.c===1?'':'s'} · ${d.r} × ${d.s}</small></h4><div class="stack-scroll">${stackSVG('w',k,front,spread)}</div></div>`).join('');$('feedSummary').innerHTML=range(d.c).map(c=>{const f=fedInput(c);return `<span class="feed-chip ${f?'on':''}" style="--channel:${channelColors[c]}"><b>c${c}</b> ${f?`n${f.n} · (${f.h},${f.w}) → <strong>${f.value}</strong>${f.valid?'':' · padding zero'}`:'<span class="annotation">no input on this edge</span><span class="quiet-symbol">—</span>'}</span>`;}).join('')+`<span class="weight-feed-note">${e?.ctl.load?`Kernel tap (${e.ctl.kr},${e.ctl.ks}) loading into B${e.ctl.writeBuffer}${e.ctl.running?' while this pass computes':''}.`:e?.state==='RUN'?'Weights remain stationary during computation.':'Kernel values move only on weight-shift edges.'}</span>`;}
