 for(let c=0;c<d.c;c++)for(let k=0;k<d.k;k++){const target=center(get(c,k)),left=center(k?get(c,k-1):grid.querySelector(`[data-feeder="${c}"] .queue-port`));lines.push(`<path class="activation-path" d="M${left.x},${target.y} H${target.x}"/>`);const wt=center(weightTarget(c,k)),top=center(c?weightTarget(c-1,k):grid.querySelector(`[data-weight-source="${k}"] .queue-port`));lines.push(`<path class="weight-path" d="M${top.x},${top.y} L${wt.x},${wt.y}"/>`);}
 layer.innerHTML=`<svg class="flow-wires" width="${grid.scrollWidth}" height="${grid.scrollHeight}" aria-hidden="true">${lines.join('')}</svg>`;
 if(!animate||!e||!$('motion').checked||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const duration=Math.max(160,Math.min(850,Number($('speed').value)*.72));
 const move=(type,value,from,to,label,attrs={})=>{const chip=document.createElement('div');chip.className=`moving-token ${type}`;chip.innerHTML=`<b>${value}</b><small>${label}</small>`;for(const [key,v]of Object.entries(attrs))chip.dataset[key]=v;layer.append(chip);chip.animate([{transform:`translate(${from.x}px,${from.y}px) translate(-50%,-50%)`,opacity:.95,offset:0},{transform:`translate(${to.x}px,${to.y}px) translate(-50%,-50%)`,opacity:1,offset:.85},{transform:`translate(${to.x}px,${to.y}px) translate(-50%,-50%)`,opacity:0,offset:1}],{duration,fill:'forwards',easing:'ease-in-out'});};
 if(e.state==='RUN')for(let c=0;c<d.c;c++)for(let k=0;k<d.k;k++){const p=sim.pe[c][k];if(!p.token)continue;const target=center(get(c,k)),from=center(k?get(c,k-1):grid.querySelector(`[data-feeder="${c}"] .queue-port`));move('activation-token',p.a,from,target,`X · c${c} · pos${p.token.pos}`,{c,k,pos:p.token.pos});}
