// Presentation preferences and fit behavior never advance the simulation clock.
let displayedQueueLimit=4;
function queuePreviewLimit(){return 4;}
function setupTextMode(){const key='cf-im2col-tiling-minimal-text-v1',button=$('minimalText');let quiet=false;try{quiet=JSON.parse(localStorage.getItem(key))===true;}catch{}
 const apply=()=>{document.body.classList.toggle('minimal-text',quiet);button.setAttribute('aria-pressed',String(quiet));button.textContent=quiet?'Show text':'Minimal text';button.title=quiet?'Restore explanatory text':'Hide explanations and secondary labels; keep values and controls';};apply();button.addEventListener('click',()=>{quiet=!quiet;apply();try{localStorage.setItem(key,JSON.stringify(quiet));}catch{}if(sim)render();window.dispatchEvent(new Event('resize'));});}
